import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/*eslint-disable*/
import AddingTerritory from "@/components/Asset/Popups/AddingTerritory.vue";
import EditTerritory from "@/components/Asset/Popups/EditTerritory.vue";
import DeleteTerritory from "@/components/Asset/Popups/DeleteTerritory.vue";
import { create_list_edit_territories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    AddingTerritory,
    SnackBar,
    EditTerritory,
    DeleteTerritory
  },
  data() {
    return {
      territoryHeaders: [{
        title: "Name",
        key: "territory_name",
        sortable: false
      }, {
        title: "Description",
        key: "territory_description",
        sortable: false
      }, {
        title: "Manager",
        key: "territory_head_name",
        sortable: false
      }, {
        title: "Action",
        key: "actions",
        sortable: false
      }],
      fixed: true,
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      createTerritoryDialog: false,
      SnackBarComponent: {},
      editTerritoryDialogue: false,
      rowInfo: {},
      deleteTerritoryDialogue: false,
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      searchQuery: ""
    };
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const query = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(item => {
        return item.territory_name && item.territory_name.toLowerCase().includes(query) || item.territory_description && item.territory_description.toLowerCase().includes(query) || item.territory_head_name && item.territory_head_name.toLowerCase().includes(query);
      });
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      // Reset to first page when search changes
      this.currentPage = 1;
    }
  },
  mounted() {
    this.windowHeight = window.innerHeight - 330;
    this.fetch_territories();
  },
  methods: {
    add_territory() {
      this.componentCheck = 1;
      this.createTerritoryDialog = true;
    },
    edit_territory(value) {
      this.rowInfo = value;
      console.log(this.rowInfo);
      this.componentCheck = 2;
      this.editTerritoryDialogue = true;
    },
    open_deletedailog(value) {
      this.rowInfo = value;
      this.componentCheck = 3;
      this.deleteTerritoryDialogue = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createTerritoryDialog = false;
      this.editTerritoryDialogue = false;
      this.deleteTerritoryDialogue = false;
      this.fetch_territories();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_territories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_territories, {
          input: {
            action_type: "LIST",
            organization_id: data.organization.organization_id
          }
          // product_name: "",
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_edit_territories);
        this.tableLoading = false;
        this.tableData = response.data;
        this.totalItems = response.data.length;
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.totalItems = 0;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
